78	/**
79	 * Push-based async iterable for streaming user messages to the Claude SDK.
80	 */
81	class MessageStream {
82	  private queue: SDKUserMessage[] = [];
83	  private waiting: (() => void) | null = null;
84	  private done = false;
85	
86	  push(text: string): void {
87	    this.queue.push({
88	      type: 'user',
89	      message: { role: 'user', content: text },
90	      parent_tool_use_id: null,
91	      session_id: '',
92	    });
93	    this.waiting?.();
94	  }
95	
96	  end(): void {
97	    this.done = true;
98	    this.waiting?.();
99	  }
100	
101	  async *[Symbol.asyncIterator](): AsyncGenerator<SDKUserMessage> {
102	    while (true) {
103	      while (this.queue.length > 0) {
104	        yield this.queue.shift()!;
105	      }
106	      if (this.done) return;
107	      await new Promise<void>((r) => {
108	        this.waiting = r;
109	      });
110	      this.waiting = null;
111	    }
112	  }
113	}
