143	function formatTranscriptMarkdown(messages: ParsedMessage[], title?: string | null, assistantName?: string): string {
144	  const now = new Date();
145	  const dateStr = now.toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true });
146	  const lines = [`# ${title || 'Conversation'}`, '', `Archived: ${dateStr}`, '', '---', ''];
147	  for (const msg of messages) {
148	    const sender = msg.role === 'user' ? 'User' : assistantName || 'Assistant';
149	    const content = msg.content.length > 2000 ? msg.content.slice(0, 2000) + '...' : msg.content;
150	    lines.push(`**${sender}**: ${content}`, '');
151	  }
152	  return lines.join('\n');
153	}
