273	/**
274	 * Locate the .jsonl backing a session id. The SDK names project dirs by a
275	 * mangled cwd; rather than reproduce that convention we scan project dirs for
276	 * `<sessionId>.jsonl` (session ids are UUIDs, so this is unambiguous).
277	 */
278	function findTranscriptPath(sessionId: string): string | null {
279	  const projects = claudeProjectsDir();
280	  let dirs: string[];
281	  try {
282	    dirs = fs.readdirSync(projects);
283	  } catch {
284	    return null;
285	  }
286	  for (const dir of dirs) {
287	    const candidate = path.join(projects, dir, `${sessionId}.jsonl`);
288	    if (fs.existsSync(candidate)) return candidate;
289	  }
290	  return null;
291	}
