314	/**
315	 * Claude Code auto-compacts context at this window (tokens). Kept here so
316	 * the generic bootstrap doesn't need to know about Claude-specific env vars.
317	 *
318	 * Operator override: set CLAUDE_CODE_AUTO_COMPACT_WINDOW in the host env to
319	 * raise or lower the threshold without editing source — useful when running
320	 * with a 1M-context model variant or when emergency-tuning a deployment.
321	 */
322	const CLAUDE_CODE_AUTO_COMPACT_WINDOW = process.env.CLAUDE_CODE_AUTO_COMPACT_WINDOW || '165000';
323	
324	/**
325	 * Stale-session detection. Matches Claude Code's error text when a
326	 * resumed session can't be found — missing transcript .jsonl, unknown
327	 * session ID, etc.
328	 */
329	const STALE_SESSION_RE = /no conversation found|ENOENT.*\.jsonl|session.*not found/i;
330	
331	export class ClaudeProvider implements AgentProvider {
332	  readonly supportsNativeSlashCommands = true;
333	
334	  private assistantName?: string;
335	  private mcpServers: Record<string, McpServerConfig>;
336	  private env: Record<string, string | undefined>;
337	  private additionalDirectories?: string[];
338	  private model?: string;
339	  private effort?: string;
340	
341	  constructor(options: ProviderOptions = {}) {
342	    this.assistantName = options.assistantName;
343	    this.mcpServers = options.mcpServers ?? {};
344	    this.additionalDirectories = options.additionalDirectories;
345	    this.model = options.model;
346	    this.effort = options.effort;
347	    this.env = {
348	      ...(options.env ?? {}),
349	      CLAUDE_CODE_AUTO_COMPACT_WINDOW,
350	    };
351	  }
352	
353	  isSessionInvalid(err: unknown): boolean {
354	    const msg = err instanceof Error ? err.message : String(err);
355	    return STALE_SESSION_RE.test(msg);
356	  }
357	
358	  maybeRotateContinuation(continuation: string): string | null {
359	    const transcriptPath = findTranscriptPath(continuation);
360	    if (!transcriptPath) return null;
361	
362	    let size: number;
363	    try {
364	      size = fs.statSync(transcriptPath).size;
365	    } catch {
366	      return null;
367	    }
368	
369	    const maxBytes = transcriptRotateBytes();
370	    const startMs = transcriptStartMs(transcriptPath);
371	    const ageMs = startMs === null ? 0 : Date.now() - startMs;
372	    const maxAgeMs = transcriptRotateAgeMs();
373	
374	    let reason: string | null = null;
375	    if (size > maxBytes) {
376	      reason = `transcript ${(size / 1_048_576).toFixed(1)}MB > ${(maxBytes / 1_048_576).toFixed(0)}MB cap`;
377	    } else if (startMs !== null && ageMs > maxAgeMs) {
378	      reason = `transcript ${(ageMs / 86_400_000).toFixed(1)}d old > ${(maxAgeMs / 86_400_000).toFixed(0)}d cap`;
379	    }
380	    if (!reason) return null;
381	
382	    // Preserve a readable summary, then move the heavy .jsonl out of the
383	    // resume path so the SDK starts a fresh session and the disk is reclaimed.
384	    archiveTranscriptFile(transcriptPath, continuation, this.assistantName);
385	    try {
386	      fs.renameSync(transcriptPath, `${transcriptPath}.rotated-${Date.now()}`);
387	    } catch (err) {
388	      log(`Failed to move rotated transcript aside: ${err instanceof Error ? err.message : String(err)}`);
389	    }
390	    return reason;
391	  }
392	
393	  query(input: QueryInput): AgentQuery {
394	    const stream = new MessageStream();
395	    stream.push(input.prompt);
396	
397	    const instructions = input.systemContext?.instructions;
398	
399	    const sdkResult = sdkQuery({
400	      prompt: stream,
401	      options: {
402	        cwd: input.cwd,
403	        additionalDirectories: this.additionalDirectories,
404	        resume: input.continuation,
405	        pathToClaudeCodeExecutable: '/pnpm/claude',
406	        systemPrompt: instructions ? { type: 'preset' as const, preset: 'claude_code' as const, append: instructions } : undefined,
407	        allowedTools: [
408	          ...TOOL_ALLOWLIST,
409	          ...Object.keys(this.mcpServers).map(mcpAllowPattern),
410	        ],
411	        disallowedTools: SDK_DISALLOWED_TOOLS,
412	        env: this.env,
413	        model: this.model,
414	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
415	        effort: this.effort as any,
416	        permissionMode: 'bypassPermissions',
417	        allowDangerouslySkipPermissions: true,
418	        settingSources: ['project', 'user', 'local'],
419	        mcpServers: this.mcpServers,
420	        hooks: {
421	          PreToolUse: [{ hooks: [preToolUseHook] }],
422	          PostToolUse: [{ hooks: [postToolUseHook] }],
423	          PostToolUseFailure: [{ hooks: [postToolUseHook] }],
424	          PreCompact: [{ hooks: [createPreCompactHook(this.assistantName)] }],
425	        },
426	      },
427	    });
428	
429	    let aborted = false;
430	
431	    async function* translateEvents(): AsyncGenerator<ProviderEvent> {
432	      let messageCount = 0;
433	      for await (const message of sdkResult) {
434	        if (aborted) return;
435	        messageCount++;
436	
437	        // Yield activity for every SDK event so the poll loop knows the agent is working
438	        yield { type: 'activity' };
439	
440	        if (message.type === 'system' && message.subtype === 'init') {
441	          yield { type: 'init', continuation: message.session_id };
442	        } else if (message.type === 'result') {
443	          const text = 'result' in message ? (message as { result?: string }).result ?? null : null;
444	          const u = (
445	            message as {
446	              usage?: {
447	                input_tokens?: number;
448	                output_tokens?: number;
449	                cache_creation_input_tokens?: number | null;
450	                cache_read_input_tokens?: number | null;
451	              };
452	            }
453	          ).usage;
454	          const usage = u
455	            ? {
456	                inputTokens: u.input_tokens ?? 0,
457	                outputTokens: u.output_tokens ?? 0,
458	                cacheCreationTokens: u.cache_creation_input_tokens ?? 0,
459	                cacheReadTokens: u.cache_read_input_tokens ?? 0,
460	              }
461	            : undefined;
462	          yield { type: 'result', text, usage };
463	        } else if (message.type === 'system' && (message as { subtype?: string }).subtype === 'api_retry') {
464	          yield { type: 'error', message: 'API retry', retryable: true };
465	        } else if (message.type === 'system' && (message as { subtype?: string }).subtype === 'rate_limit_event') {
466	          yield { type: 'error', message: 'Rate limit', retryable: false, classification: 'quota' };
467	        } else if (message.type === 'system' && (message as { subtype?: string }).subtype === 'compact_boundary') {
468	          const meta = (message as { compact_metadata?: { pre_tokens?: number } }).compact_metadata;
469	          const detail = meta?.pre_tokens ? ` (${meta.pre_tokens.toLocaleString()} tokens compacted)` : '';
470	          yield { type: 'result', text: `Context compacted${detail}.` };
471	        } else if (message.type === 'system' && (message as { subtype?: string }).subtype === 'task_notification') {
472	          const tn = message as { summary?: string };
473	          yield { type: 'progress', message: tn.summary || 'Task notification' };
474	        }
475	      }
476	      log(`Query completed after ${messageCount} SDK messages`);
477	    }
478	
479	    return {
480	      push: (msg) => stream.push(msg),
481	      end: () => stream.end(),
482	      events: translateEvents(),
483	      abort: () => {
484	        aborted = true;
485	        stream.end();
486	      },
487	    };
488	  }
489	}
490	
491	registerProvider('claude', (opts) => new ClaudeProvider(opts));
