290	          parts.push(formatMessages(normalBatch));
291	          normalBatch.length = 0;
292	        }
293	        // Pass raw command text (no XML wrapping) — SDK handles it natively
294	        parts.push(cmdInfo.text);
295	        continue;
296	      }
297	    }
